package dev.baranhan.viltrumitecore.client.ghostrider;

import net.minecraft.resources.ResourceLocation;

/** Resource locations of the Ghost Rider's client assets (generated by tools/assets/ghost_rider_*.py). */
public final class GhostRiderAssets {
   public static final ResourceLocation BIKE_GEO = rl("geo/ghost_rider/hell_cycle.geo.json");
   public static final ResourceLocation BIKE_TEX = rl("textures/entity/ghost_rider/hell_cycle.png");
   public static final ResourceLocation BIKE_GLOW = rl("textures/entity/ghost_rider/hell_cycle_glow.png");
   public static final ResourceLocation HELLFIRE = rl("textures/entity/ghost_rider/hellfire.png");

   private GhostRiderAssets() {
   }

   static ResourceLocation rl(String path) {
      return new ResourceLocation("viltrumitecore", path);
   }
}
